const filters={};
function currentFilter(key){if(!filters[key])filters[key]={q:'',stage:'All'};return filters[key]}
function rowMatches(row,filter,key){const q=filter.q.trim().toLowerCase();let vals=Object.values(row).map(x=>String(x??'')).join(' ').toLowerCase();let stageKey=key==='tasks'?'status':key==='content'?'stage':key==='emails'?'status':'stage';return (!q||vals.includes(q))&&(filter.stage==='All'||String(row[stageKey]||'')===filter.stage)}
function tableRows(key){const f=currentFilter(key);const data=state[key].filter(x=>rowMatches(x,f,key));if(!data.length)return '<tr><td colspan="'+(COLS[key].length+1)+'"><div class="empty">No matching entries. Use “New record” to add an item, or clear filters.</div></td></tr>';return data.map(row=>'<tr>'+COLS[key].map(([field,name])=>{let val=row[field];let v='';if(field==='stage'||field==='status'||field==='priority'||field==='tier')v=chip(val);else if(field==='scenarioId')v='<a class="mono" target="_blank" rel="noopener noreferrer" href="https://eu2.make.com/715909/scenarios/'+e(Number(val)||'')+'">'+e(val)+'</a>';else if(field==='source'&&url(val))v='<a class="text-link" href="'+e(url(val))+'" target="_blank" rel="noopener noreferrer">View evidence ↗</a>';else if(field==='price'||field==='potentialValue')v=money(val);else if(field==='name'||field==='title')v='<span class="primary-cell">'+e(val)+'</span><small>'+e(row.id||'')+'</small>';else v=e(String(val??'').slice(0,100))+(String(val??'').length>100?'…':'');return '<td>'+v+'</td>'}).join('')+'<td><div class="row-actions"><button class="btn small ghost" data-action="view" data-entity="'+key+'" data-id="'+e(row.id)+'">View</button><button class="btn small ghost" data-action="edit" data-entity="'+key+'" data-id="'+e(row.id)+'">Edit</button><button class="btn small danger" data-action="delete" data-entity="'+key+'" data-id="'+e(row.id)+'">×</button></div></td></tr>').join('')}
