function productIsReleased(p){return ['Ready','Published'].includes(p.stage)&&p.blueprint&&p.importTest&&p.runtimeTest&&p.listingApproved}
function catalogCover(p,small=false){if(/^(VAVE-AIC-(0[1-9]|1[0-2])|VAVE-BIZ-0[1-3])$/.test(String(p.id))){return '<div class="catalog-cover '+(small?'compact ':'')+'image-cover" style="padding:0;overflow:hidden;background:#07172b"><img src="'+e(root+'assets/product-covers/'+p.id+'.svg')+'" alt="" loading="lazy" width="1200" height="675" style="display:block;width:100%;height:auto;min-height:170px;object-fit:cover"></div>'}const tags=String(p.tags||'').split(',').filter(Boolean);const isBiz=p.category==='Business';const mark=isBiz?'B':'C';return '<div class="catalog-cover '+(isBiz?'biz':'creator')+(small?' compact':'')+'"><div class="catalog-cover-top"><span class="catalog-monogram">V<span class="accent-spark">/</span></span><span class="catalog-corner">'+(isBiz?'BUSINESS SYSTEMS':'CREATOR LAB')+'</span></div><div class="catalog-cover-middle"><span class="catalog-graphic">'+e(mark)+'</span><strong>'+e(p.name.replace(/^Vave /,''))+'</strong></div><div class="catalog-cover-bottom"><span>MAKE WORKFLOW</span><span>'+e(p.id)+'</span></div></div>'}
function catalogCard(p){const released=productIsReleased(p),detail=catalogLink(p.id);return '<a class="catalog-card" href="'+e(detail)+'" data-catalog-card="true" data-category="'+e(p.category||'')+'" data-search="'+e([p.name,p.id,p.pitch,p.category,p.tags,p.audience].join(' ').toLowerCase())+'">'+catalogCover(p)+'<div class="catalog-card-body"><div class="catalog-meta">'+chip(released?'Ready':p.stage||'Development')+' <span class="catalog-price">'+money(p.price)+' <small>proposed</small></span></div><h3>'+e(p.name)+'</h3><p>'+e(p.pitch||'Description pending.')+'</p><div class="catalog-footer"><span>'+e(p.category||'Collection')+'</span><b>View product ↗</b></div></div></a>'}
function catalogPage(){const products=state.products||[],released=products.filter(productIsReleased).length;return head('Vave products / all collections','Product Catalog','Browse all current development products like a storefront. Open any card for complete specs, notes, release checks and editing.',btn('+ New product','new','primary','data-entity="products"'))+metrics([['Product records',products.length,'Includes new items you add',true],['Creator Lab',products.filter(p=>p.category==='Creator Lab').length,'Development catalog'],['Business',products.filter(p=>p.category==='Business').length,'Development catalog'],['Release-approved',released,'Not equivalent to Gumroad sales']])+'<div class="callout warn"><strong>Internal catalog, not the Gumroad store.</strong> Prices are proposed. Only products passing release evidence can be described as ready; no scenarios have been run from this HQ. Edits are browser-local until backed up. <a href="'+e(root+'systems/launch-packs.html')+'" style="color:#c9e8ff;font-weight:700;text-decoration:underline">Open the 15 packaging dossiers →</a></div><div class="catalog-toolbar"><div><span class="eyebrow">PRODUCT COLLECTIONS</span><h2>Built for practical workflows.</h2></div><input id="catalog-query" class="input" type="search" placeholder="Search by name, type or use case…" aria-label="Search product catalog"><select id="catalog-category" class="select" aria-label="Filter product collection"><option value="All">All products</option><option value="Creator Lab">Creator Lab</option><option value="Business">Business</option></select></div><div id="catalog-count" class="catalog-count">Showing '+products.length+' products</div><div id="catalog-grid" class="catalog-grid">'+products.map(catalogCard).join('')+'</div><div id="catalog-empty" class="empty" hidden>No products match your filters.</div><div class="callout" style="margin-top:20px">Adding a new product here also adds it to the Product Studio release registry. Use Settings → Backup to export the current data, especially before switching browsers or devices.</div>'}
function productField(name,value){return '<div class="detail-field"><span>'+e(name)+'</span><p>'+e(value||'Not documented yet')+'</p></div>'}
function productDetailPage(){const key=new URLSearchParams(location.search).get('id')||'',p=state.products.find(x=>x.id===key);if(!p)return head('Product detail','Product not found','This product may have been removed from this browser workspace.')+'<a class="btn primary" href="'+navhref('catalog')+'">← Back to catalog</a>';const released=productIsReleased(p);const evid=[['Blueprint exported',p.blueprint],['Clean import verified',p.importTest],['Runtime QA passed',p.runtimeTest],['Listing approved',p.listingApproved]];const makeLink=p.scenarioId?'https://eu2.make.com/715909/scenarios/'+encodeURIComponent(p.scenarioId):'';const slug=String(p.tags||'').split(',').map(x=>x.trim()).filter(Boolean);return '<div class="detail-back"><a href="'+navhref('catalog')+'">← All products</a><span>'+e(p.id)+'</span></div><div class="catalog-detail-hero"><div>'+catalogCover(p,true)+'</div><div class="detail-hero-content"><div class="eyebrow">'+e(p.category||'Uncategorized')+' / '+e(p.version||'Development')+'</div><h1>'+e(p.name)+'</h1><p>'+e(p.positioning||p.pitch||'Product information pending.')+'</p><div class="detail-price">'+money(p.price)+' <span>proposed price · not live</span></div><div class="detail-status">'+chip(released?'Ready':p.stage||'Development')+'<span>'+(released?'Release evidence checked locally; confirm official proof':'Not available to purchase')+'</span></div><div class="detail-actions">'+btn('✎ Edit details','edit','primary','data-entity="products" data-id="'+e(p.id)+'"')+(makeLink?'<a class="btn ghost" target="_blank" rel="noopener noreferrer" href="'+e(makeLink)+'">Open Make scenario ↗</a>':'')+(p.storeUrl&&released?'<a class="btn ghost" target="_blank" rel="noopener noreferrer" href="'+e(url(p.storeUrl))+'">Open Gumroad ↗</a>':'')+'</div></div></div><div class="detail-layout"><div><div class="detail-section"><span class="eyebrow">PRODUCT OVERVIEW</span><h2>What it actually does</h2><p>'+e(p.pitch||'To be scoped')+'</p></div><div class="detail-section"><span class="eyebrow">BUYER WORKFLOW</span><h2>Who it is for</h2>'+productField('Ideal buyer',p.audience)+productField('Example scenario',p.examples)+'</div><div class="detail-section"><span class="eyebrow">INPUTS & OUTPUTS</span><h2>How the automation is intended to work</h2>'+productField('Buyer input',p.inputs)+productField('Draft output',p.outputs)+productField('Requirements',p.requirements)+'</div><div class="detail-section"><span class="eyebrow">DELIVERY & SETUP</span><h2>Customer package plan</h2>'+productField('Planned downloadable files',p.contents)+productField('Proposed installation outline',p.setup)+'<div class="callout warn">Package contents are planned, not guaranteed or verified until the release checklist is completed.</div></div><div class="detail-section"><span class="eyebrow">TRUTH IN LISTING</span><h2>Limitations & compliance</h2><p>'+e(p.limits||'Define limitations before launch')+'</p></div></div><aside class="detail-sidebar"><div class="detail-section"><span class="eyebrow">PRODUCT STATUS</span><h3>Release requirements</h3><div class="detail-checks">'+evid.map(x=>'<div><span class="'+(x[1]?'good':'pending')+'">'+(x[1]?'✓':'—')+'</span> '+e(x[0])+'</div>').join('')+'</div><div class="detail-note">Only checking boxes locally is not independent proof of QA. Keep original evidence before selling.</div></div><div class="detail-section"><span class="eyebrow">PRODUCT PROFILE</span>'+productField('SKU',p.id)+productField('Make scenario ID',p.scenarioId||'Not assigned')+productField('Owner',p.owner||'Unassigned')+productField('Next action',p.nextAction)+productField('Work notes',p.notes)+'</div><div class="detail-section"><span class="eyebrow">ASSETS & LINKS</span>'+(p.productDocUrl&&url(p.productDocUrl)?'<p><a href="'+e(url(p.productDocUrl))+'" target="_blank" rel="noopener noreferrer">Product documentation ↗</a></p>':'<p class="text-muted">Documentation link not set.</p>')+(p.storeUrl&&url(p.storeUrl)?'<p><a href="'+e(url(p.storeUrl))+'" target="_blank" rel="noopener noreferrer">Gumroad URL (not verified) ↗</a></p>':'<p class="text-muted">Gumroad listing not linked.</p>')+'<div class="chip-group">'+slug.map(x=>'<span class="chip">'+e(x)+'</span>').join('')+'</div></div></aside></div>'}
function refreshCatalog(){const q=(document.getElementById('catalog-query')?.value||'').toLowerCase().trim();const cat=document.getElementById('catalog-category')?.value||'All';let shown=0;document.querySelectorAll('[data-catalog-card]').forEach(el=>{let ok=(!q||el.dataset.search.includes(q))&&(cat==='All'||el.dataset.category===cat);el.hidden=!ok;if(ok)shown++});const count=document.getElementById('catalog-count');if(count)count.textContent='Showing '+shown+' of '+state.products.length+' products';const empty=document.getElementById('catalog-empty');if(empty)empty.hidden=shown!==0}

function affiliatePage(){const a=state.affiliates,t=activeTab('pipeline');let tierA=a.filter(x=>x.tier==='A').length;let contacted=a.filter(x=>['Contacted','Replied','Approved','Active'].includes(x.stage)).length;let active=a.filter(x=>x.stage==='Active').length;let top=head('Distribution department','Affiliate Command Center','A real creator prospect database, qualification process, onboarding approach and launch conversion system.',btn('+ Add creator','new','primary','data-entity="affiliates"'));top+=metrics([['Sourced candidates',a.length,'Research ≠ accepted partners',true],['Tier A candidates',tierA,'Score is a research estimate'],['Contacted',contacted,'Only manual statuses in this browser'],['Activated affiliates',active,'No tracked sales connected']]);top+=tabbar([['pipeline','Research CRM'],['playbook','Recruitment playbook'],['economics','Offer & economics']],t);
if(t==='playbook')return top+section('Creator partnership operating procedure','Optimize response quality, not only outbound volume')+steps([['Source 25 relevant creators per batch','Favor 2k–100k follower tutorial niches and observable engagement; no unverifiable reach claims.'],['Score against one concrete product','Assess audience fit, recent posts, contactability, direct competition and the creator’s teaching style.'],['Verify actual public contact','Follow platform rules; do not scrape private emails or guess addresses. Use opt-out/suppression records.'],['Personalize a concise outreach','Mention a specific public tutorial and invite an honest walkthrough of one tested workflow.'],['Offer proof, not promises','Give a working product demo, installer guide, commission terms and correct sponsored-content disclosures.'],['Measure conversion and retention','Record visits, verified sales, refund signals, and questions. Expand the program only after repeatable performance.']])+'<div class="grid two" style="margin-top:18px">'+card('Initial cohort design','Qualify 10 excellent candidates, approach 5 thoughtfully, and aim for the first 1–3 active partners. No automated bulk DMs.','FIRST COHORT')+card('Pipeline discipline','Every row should have: proof source, product fit, verified contact route, last touch, next step and conflict check.','CRM STANDARD')+'</div>';
if(t==='economics')return top+section('Provisional partner offer','Financial terms are proposals, not approved contracts')+'<div class="grid three">'+card('Entry commission','Owner-set 60% of qualifying attributed product sales. Configure it in Gumroad and verify fees, refunds and account eligibility before activation.','COMPENSATION')+card('Creative package','Genuine demo, product thumbnail, 3 unique short-form hooks, correct feature list, FAQ and campaign-specific affiliate link.','ENABLEMENT')+card('Guardrails','Clearly disclose paid affiliate relationships. No fabricated results, personal income promises, spam, or selling an untested product.','COMPLIANCE')+'</div>'+section('Simple contribution estimate','Illustrative only; editable pricing is in the Product Studio')+'<div class="grid two">'+card('Example: $29 product','60% commission is $17.40 on a $29 sale, leaving $11.60 before marketplace fees, refunds, support and tax.','SCENARIO')+card('First partner evaluation','After a suitable trial: review qualified visits, purchases, refunds, support load and content quality.','DECISION')+'</div>';
return top+'<div class="callout">Public preview excludes the internal creator research database. Add only non-sensitive demonstration records here; any browser edits remain local to your own device.</div>'+section('Affiliate prospect intelligence','Filter by stage, tier or creator niche')+renderTable('affiliates')+section('Activation funnel','Derived entirely from local tracked stages')+'<div class="card">'+barSeries(['Researched','Qualified','Outreach drafted','Contacted','Replied','Approved','Active'].map(x=>[x,a.filter(y=>y.stage===x).length]))+'</div>'+
 section('Outreach starter','Editable example; personalization required')+'<div class="card"><div class="subhead">COLLABORATION TEMPLATE</div><p id="affiliate-template">Hi — I came across your tutorial on [SPECIFIC PUBLIC TOPIC]. I’m preparing a documented Make workflow for [RELEVANT AUDIENCE]. Would you be interested in taking an independent look at a real demo and giving feedback? If it fits your audience after testing, there may be a transparent affiliate option. No pressure either way.</p><div style="margin-top:12px">'+btn('Copy outreach template','copy-affiliate','ghost')+'</div></div>'}
