if(t==='playbook')return top+section('Production workflow','Every content asset should have one demonstrated value')+steps([['Choose a credible product use case','Start with a verified input and show genuine output.'],['Write a useful hook','Name a real pain point; avoid claiming guaranteed reach or revenue.'],['Capture the workflow','Record the actual Make steps and output only after QA.'],['Translate into 3 short-form formats','Demo, educational checklist and behind-the-scenes explanation.'],['Connect to a valid CTA','Free resource, opt-in or verified Gumroad page. Never use a fictitious coupon link.'],['Review results','Collect saves, questions, qualified visits and real sales—not views alone.']])+'<div class="grid three" style="margin-top:18px">'+card('Demonstrations','Video walkthroughs showing a real before/after and honest requirements.','PILLAR')+card('Education','Make setup, blueprint imports, safeguards and workflow ideas.','PILLAR')+card('Product updates','New releases, improvements, reviews and customer FAQs after verification.','PILLAR')+'</div>';
